import { useState, useCallback, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Wifi, Download, Upload, Activity, Server } from 'lucide-react';
import { ResponsiveContainer, AreaChart, Area, XAxis, Tooltip } from 'recharts';
import './index.css';

function SpeedChecker() {
  const [download, setDownload] = useState(0);
  const [upload, setUpload] = useState(0);
  const [ping, setPing] = useState(0);
  const [testing, setTesting] = useState(false);
  const [history, setHistory] = useState([]);

  const [network, setNetwork] = useState({
    isp: 'Detecting...',
    server: 'Detecting...',
    location: 'Detecting...',
    ip: 'Detecting...',
  });

  const API_BASE = process.env.REACT_APP_API_URL || window.location.origin;

  const getMedian = (arr) => {
    if (!arr.length) return 0;

    const sorted = [...arr].sort((a, b) => a - b);
    const middle = Math.floor(sorted.length / 2);

    if (sorted.length % 2 === 0) {
      return (sorted[middle - 1] + sorted[middle]) / 2;
    }

    return sorted[middle];
  };

  const removeSpikes = (samples) => {
    if (samples.length < 4) return samples;

    const median = getMedian(samples);

    return samples.filter((speed) => {
      return speed > median * 0.45 && speed < median * 1.65;
    });
  };

  const loadNetworkInfo = useCallback(async () => {
    try {
      const res = await fetch('https://ipwho.is/', {
        cache: 'no-store',
      });

      const data = await res.json();

      if (data?.success) {
        setNetwork({
          isp: data.connection?.isp || data.connection?.org || 'Unknown ISP',
          server: 'Nearest Test Server',
          location: `${data.city || ''}${data.city ? ', ' : ''}${data.country || ''}`,
          ip: data.ip || 'Hidden',
        });

        return;
      }

      throw new Error('Network info failed');
    } catch (error) {
      console.error('Network info error:', error);

      setNetwork({
        isp: 'Unable to detect',
        server: 'Nearest Test Server',
        location: 'Unable to detect',
        ip: 'Hidden',
      });
    }
  }, []);

  useEffect(() => {
    loadNetworkInfo();
  }, [loadNetworkInfo]);

  const runTest = useCallback(async () => {
    try {
      setTesting(true);
      setDownload(0);
      setUpload(0);
      setPing(0);
      setHistory([]);

      await loadNetworkInfo();

      // ================= PING =================
      const pingSamples = [];

      for (let i = 0; i < 5; i++) {
        const start = performance.now();

        await fetch(`${API_BASE}/api/ping?t=${Date.now()}-${i}`, {
          cache: 'no-store',
        });

        pingSamples.push(performance.now() - start);
      }

      setPing(Math.round(getMedian(pingSamples)));

      // ================= DOWNLOAD - STABLE REAL-WORLD LOGIC =================
      const DOWNLOAD_DURATION = 12000;
      const DOWNLOAD_SIZE = 30 * 1024 * 1024;
      const SAMPLE_INTERVAL = 1000;
      const WARMUP_TIME = 3000;

      let totalDownloadedBytes = 0;
      let lastSampleBytes = 0;
      let lastSampleTime = performance.now();

      const downloadStart = performance.now();
      const downloadSamples = [];

      while (performance.now() - downloadStart < DOWNLOAD_DURATION) {
        const res = await fetch(`${API_BASE}/api/download?size=${DOWNLOAD_SIZE}&t=${Date.now()}`, {
          cache: 'no-store',
        });

        if (!res.body) {
          throw new Error('Download stream not supported');
        }

        const reader = res.body.getReader();

        while (true) {
          const { value, done } = await reader.read();

          if (done) break;

          totalDownloadedBytes += value.byteLength;

          const now = performance.now();
          const elapsed = now - downloadStart;
          const sampleElapsed = now - lastSampleTime;

          if (sampleElapsed >= SAMPLE_INTERVAL) {
            const bytesInSample = totalDownloadedBytes - lastSampleBytes;
            const seconds = sampleElapsed / 1000;
            const mbps = (bytesInSample * 8) / seconds / 1_000_000;

            if (elapsed > WARMUP_TIME && Number.isFinite(mbps) && mbps > 0) {
              downloadSamples.push(mbps);

              const stableSamples = removeSpikes(downloadSamples);
              const displaySpeed = Math.round(getMedian(stableSamples));

              setDownload(displaySpeed);

              setHistory((prev) => [
                ...prev.slice(-25),
                {
                  time: prev.length + 1,
                  speed: displaySpeed,
                },
              ]);
            }

            lastSampleTime = now;
            lastSampleBytes = totalDownloadedBytes;
          }

          if (performance.now() - downloadStart >= DOWNLOAD_DURATION) {
            break;
          }
        }
      }

      const cleanDownloadSamples = removeSpikes(downloadSamples);
      const finalDownload = Math.round(getMedian(cleanDownloadSamples));

      setDownload(finalDownload);

      // ================= UPLOAD - STABLE LOGIC =================
      const UPLOAD_DURATION = 8000;
      const UPLOAD_SIZE = 1024 * 1024;
      const UPLOAD_SAMPLE_INTERVAL = 1000;
      const UPLOAD_WARMUP_TIME = 2000;

      const uploadChunk = new Uint8Array(UPLOAD_SIZE);

      let totalUploadedBytes = 0;
      let lastUploadBytes = 0;
      let lastUploadTime = performance.now();

      const uploadStart = performance.now();
      const uploadSamples = [];

      while (performance.now() - uploadStart < UPLOAD_DURATION) {
        await fetch(`${API_BASE}/api/upload?t=${Date.now()}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/octet-stream',
          },
          body: uploadChunk,
          cache: 'no-store',
        });

        totalUploadedBytes += uploadChunk.byteLength;

        const now = performance.now();
        const elapsed = now - uploadStart;
        const sampleElapsed = now - lastUploadTime;

        if (sampleElapsed >= UPLOAD_SAMPLE_INTERVAL) {
          const bytesInSample = totalUploadedBytes - lastUploadBytes;
          const seconds = sampleElapsed / 1000;
          const mbps = (bytesInSample * 8) / seconds / 1_000_000;

          if (elapsed > UPLOAD_WARMUP_TIME && Number.isFinite(mbps) && mbps > 0) {
            uploadSamples.push(mbps);

            const stableUploadSamples = removeSpikes(uploadSamples);
            const displayUpload = Math.round(getMedian(stableUploadSamples));

            setUpload(displayUpload);
          }

          lastUploadTime = now;
          lastUploadBytes = totalUploadedBytes;
        }
      }

      const cleanUploadSamples = removeSpikes(uploadSamples);
      const finalUpload = Math.round(getMedian(cleanUploadSamples));

      setUpload(finalUpload);
    } catch (err) {
      console.error(err);
      alert(err.message || 'Speed test failed');
    } finally {
      setTesting(false);
    }
  }, [API_BASE, getMedian, loadNetworkInfo]);

  return (
    <div className="speed-page">
      <div className="speed-app">
        <header className="topbar">
          <h1 className="logo-text">⚡ SpeedChecker</h1>

          <button className="run-btn" onClick={runTest} disabled={testing}>
            {testing ? 'Testing...' : 'Start Test'}
          </button>
        </header>

        <main>
          <section className="hero-section">
            <div className="speed-value">{download}</div>
            <div className="speed-unit">Mbps</div>

            <div className={`neon-ring ${testing ? 'ring-active' : ''}`}>
              <div className="ring-inner">
                <Wifi size={34} />
                <span>{testing ? 'Running' : 'Ready'}</span>
              </div>
            </div>

            <p className="status-text">
              {testing
                ? 'Testing sustained internet speed...'
                : 'Click start to test your connection'}
            </p>
          </section>

          <section className="cards">
            <div className="card">
              <Download size={22} />
              <p>Download</p>
              <h3>{download} Mbps</h3>
            </div>

            <div className="card">
              <Upload size={22} />
              <p>Upload</p>
              <h3>{upload} Mbps</h3>
            </div>

            <div className="card">
              <Activity size={22} />
              <p>Ping</p>
              <h3>{ping} ms</h3>
            </div>

            <div className="card">
              <Server size={22} />
              <p>Status</p>
              <h3>{testing ? 'Running' : 'Stable'}</h3>
            </div>
          </section>

          <section className="graph-box">
            <h2>Live Speed Graph</h2>

            <ResponsiveContainer width="100%" height={250}>
              <AreaChart data={history}>
                <XAxis dataKey="time" hide />
                <Tooltip
                  contentStyle={{
                    background: '#050816',
                    border: '1px solid #00f7ff',
                    borderRadius: '12px',
                    color: '#fff',
                  }}
                />
                <Area
                  type="monotone"
                  dataKey="speed"
                  stroke="#00f7ff"
                  fill="rgba(0,247,255,0.2)"
                  strokeWidth={3}
                />
              </AreaChart>
            </ResponsiveContainer>
          </section>

          <section className="network-box">
            <h2>Network Details</h2>

            <div className="network-grid">
              <div>
                <span>ISP</span>
                <strong>{network.isp}</strong>
              </div>

              <div>
                <span>Server</span>
                <strong>{network.server}</strong>
              </div>

              <div>
                <span>Location</span>
                <strong>{network.location}</strong>
              </div>

              <div>
                <span>IP Address</span>
                <strong>{network.ip}</strong>
              </div>
            </div>
          </section>

          <section className="seo-box">
            <h2>How Fast Is Your Internet?</h2>
            <p>
              Test your download speed, upload speed, ping and network stability instantly with
              SpeedChecker.
            </p>
          </section>
        </main>

        <footer className="footer">
          <Link to="/privacy-policy">Privacy</Link>
          <Link to="/terms-of-service">Terms</Link>
          <Link to="/about-us">About</Link>
        </footer>
      </div>
    </div>
  );
}

export default SpeedChecker;
